#!/bin/bash
usage() { echo "usage: $0 [-v] [-n NAME] [-c COUNT] FILE..." >&2; exit 2; }

verbose=0; name=world; count=1
while getopts ":vn:c:h" opt; do
    case $opt in
        v) verbose=1 ;;
        n) name=$OPTARG ;;
        c) count=$OPTARG ;;
        h) usage ;;
        :) echo "option -$OPTARG needs an argument" >&2; exit 2 ;;
        \?) echo "unknown option -$OPTARG" >&2; exit 2 ;;
    esac
done
shift $((OPTIND - 1))               # what is left are the positional arguments

[ "$verbose" = 1 ] && echo "verbose mode on"
for ((i = 1; i <= count; i++)); do echo "hello $name ($i)"; done
echo "files: $*"
